import{ht as e,nt as t,o as n,tt as r}from"./chunks/framework.BDx6F-5s.js";var i=JSON.parse(`{"title":"技術用語集","description":"SyncETAの主要用語定義：Record、Scenario、Collection、Story、Dataset、MCP、Visual Regression、Self-Healing。","frontmatter":{"title":"技術用語集","description":"SyncETAの主要用語定義：Record、Scenario、Collection、Story、Dataset、MCP、Visual Regression、Self-Healing。","sort":1200,"head":[["link",{"rel":"canonical","href":"https://empasy.io/docs/ja/synceta/glossary.html"}]]},"headers":[],"relativePath":"ja/synceta/glossary.md","filePath":"ja/synceta/glossary.md","lastUpdated":1787441667000}`),a={name:`ja/synceta/glossary.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="技術用語集" tabindex="-1">技術用語集 <a class="header-anchor" href="#技術用語集" aria-label="Permalink to “技術用語集”">​</a></h1><p>SyncETAプラットフォームで使用される主要用語の定義です。</p><hr><h3 id="record-レコード" tabindex="-1">Record（レコード） <a class="header-anchor" href="#record-レコード" aria-label="Permalink to “Record（レコード）”">​</a></h3><p>ブラウザ操作およびDOM情報を記録する最小単位。XPath、セレクター、属性情報を保持します。</p><h3 id="scenario-シナリオ" tabindex="-1">Scenario（シナリオ） <a class="header-anchor" href="#scenario-シナリオ" aria-label="Permalink to “Scenario（シナリオ）”">​</a></h3><p>一連のレコードで構成されるエンドツーエンドのテストケース単位。待機条件や検証条件を含みます。</p><h3 id="collection-コレクション" tabindex="-1">Collection（コレクション） <a class="header-anchor" href="#collection-コレクション" aria-label="Permalink to “Collection（コレクション）”">​</a></h3><p>複数のシナリオを順次または並列に一括実行するためのテストスイート。</p><h3 id="story-ストーリー" tabindex="-1">Story（ストーリー） <a class="header-anchor" href="#story-ストーリー" aria-label="Permalink to “Story（ストーリー）”">​</a></h3><p>フローチャート形式でシナリオを結合し、同一ブラウザセッションで連続実行するワークフロー。</p><h3 id="dataset-データセット" tabindex="-1">Dataset（データセット） <a class="header-anchor" href="#dataset-データセット" aria-label="Permalink to “Dataset（データセット）”">​</a></h3><p>シナリオの入力値をパラメータ化するためのテーブル形式リポジトリ。</p><h3 id="playwright-mcp" tabindex="-1">Playwright MCP <a class="header-anchor" href="#playwright-mcp" aria-label="Permalink to “Playwright MCP”">​</a></h3><p>Model Context Protocol（MCP）標準を介してブラウザ自動化ツールを提供する実行エンジン。</p><h3 id="visual-regression-ai-視覚的回帰検証" tabindex="-1">Visual Regression AI（視覚的回帰検証） <a class="header-anchor" href="#visual-regression-ai-視覚的回帰検証" aria-label="Permalink to “Visual Regression AI（視覚的回帰検証）”">​</a></h3><p>画像認識により要素の重なりやレイアウト崩れを人間認知観点で検証する機能。</p><h3 id="self-healing-自己修復" tabindex="-1">Self-Healing（自己修復） <a class="header-anchor" href="#self-healing-自己修復" aria-label="Permalink to “Self-Healing（自己修復）”">​</a></h3><p>UI変更時に壊れたセレクターを検知し、代替候補を算出して管理者の承認を経て復旧する仕組み。</p><h3 id="air-gapped-オンプレミス" tabindex="-1">Air-Gapped / オンプレミス <a class="header-anchor" href="#air-gapped-オンプレミス" aria-label="Permalink to “Air-Gapped / オンプレミス”">​</a></h3><p>外部通信が遮断された閉域網環境下で社内モデル基盤と連携して独立稼働する配備形態。</p>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};